        switch(action){
            case "submit"->{if(!old.equals("DRAFT"))throw state("只有草稿可以提交");status="PENDING_AUDIT";}
            case "audit"->{if(!old.equals("PENDING_AUDIT"))throw state("只有待审核凭证可审核");if(number(v,"preparedBy")==a.userId())throw new ApiException(400,"FIN_AUDITOR_CONFLICT","审核人不能是编制人");status="AUDITED";jdbc.update("UPDATE fin_voucher SET audited_by=?,audited_at=clock_timestamp() WHERE country_id=? AND id=?",a.userId(),a.requireCountry(),id);}
            case "unaudit"->{if(!old.equals("AUDITED"))throw state("只有已审核未记账凭证可取消审核");String reason=Inputs.required(b,"reason");status="PENDING_AUDIT";jdbc.update("UPDATE fin_voucher SET unaudit_reason=?,audited_by=NULL,audited_at=NULL,status='PENDING_AUDIT' WHERE country_id=? AND id=?",reason,a.requireCountry(),id);}
            case "post"->{if(!old.equals("AUDITED"))throw state("只有已审核凭证可以记账");if(v.get("auditedBy")==null||Objects.equals(v.get("preparedBy"),v.get("auditedBy")))throw new ApiException(400,"FIN_AUDITOR_CONFLICT","编制审核必须分离");var lines=validation.lines(a,book,castLines(v.get("lines")),!"MANUAL".equals(v.get("sourceKind")),!"MANUAL".equals(v.get("sourceKind")));lockDimensions(a,book,lines);if(jdbc.queryForObject("SELECT count(*) FROM fin_period WHERE country_id=? AND book_id=? AND start_date>? AND status='CLOSED'",Integer.class,a.requireCountry(),book,LocalDate.parse(v.get("voucherDate").toString()))>0)throw new ApiException(400,"FIN_LATER_CLOSED","后续期间已结账，不能补记此前期间");
                jdbc.update("UPDATE fin_voucher SET status='POSTED',posted_by=?,posted_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=?",a.userId(),a.requireCountry(),id);long period=number(v,"periodId");for(var l:groupDimensions(lines)){BigDecimal d=dec(l,"debit"),cr=dec(l,"credit"),net=d.subtract(cr),orig=dec(l,"origDelta");increment(a,book,period,l,BigDecimal.ZERO,d,cr,orig);for(var p:jdbc.queryForList("SELECT id FROM fin_period WHERE country_id=? AND book_id=? AND start_date>? AND status IN ('OPEN','PENDING_CLOSE') ORDER BY start_date",a.requireCountry(),book,LocalDate.parse(v.get("voucherDate").toString())))increment(a,book,((Number)p.get("id")).longValue(),l,net,BigDecimal.ZERO,BigDecimal.ZERO,orig);}
                if(v.get("reversalOfId")!=null)jdbc.update("UPDATE fin_voucher SET status='REVERSED',reversed_by_id=?,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=? AND status='POSTED'",id,a.requireCountry(),v.get("reversalOfId"));audit.append(a.requireCountry(),a.userId(),"记账","FIN_VOUCHER",id,v,Map.of("status","POSTED"),null);return voucher(a,book,id,false);
            }
            default->throw ApiException.notFound();
        }
